import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import { createManifest, verifyManifest } from '../snapshot.js';

const script = fileURLToPath(new URL('../snapshot.js', import.meta.url));
function fixture(t) {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'snapshot-extra-'));
  t.after(() => fs.rmSync(root, {recursive:true, force:true}));
  return root;
}
function put(root, name, bytes = 'abc') {
  fs.mkdirSync(path.dirname(path.join(root, name)), {recursive:true});
  fs.writeFileSync(path.join(root, name), bytes);
  fs.chmodSync(path.join(root, name), 0o640);
}
const blank = () => ({ok:true, unchanged:[], changed:[], missing:[], unsafe:[]});

test('sorted exhaustive drift, exact bytes, unusual names, immutable input', t => {
  const root = fixture(t);
  const names = ['z', 'A', 'é', 'space tab\tline\n', 'both', 'mode', 'gone/file', 'link/file', 'blocked/file', 'directory', 'dangling', 'size'];
  for (const name of names) put(root, name, Buffer.from([0, 255, 10]));
  Object.freeze(names);
  const manifest = createManifest(root, names);
  assert.deepEqual(manifest.files.map(e => e.path), [...names].sort());
  manifest.files.reverse();
  manifest.files.forEach(Object.freeze);
  Object.freeze(manifest.files);
  Object.freeze(manifest);
  const before = JSON.stringify(manifest);
  assert.deepEqual(verifyManifest(root, manifest), {...blank(), unchanged:[...names].sort()});
  put(root, 'z', 'xyz');
  put(root, 'both', 'changed'); fs.chmodSync(path.join(root, 'both'), 0o600);
  fs.chmodSync(path.join(root, 'mode'), 0o600);
  fs.rmSync(path.join(root, 'gone'), {recursive:true});
  fs.rmSync(path.join(root, 'link'), {recursive:true});
  fs.symlinkSync(root, path.join(root, 'link'));
  fs.rmSync(path.join(root, 'blocked'), {recursive:true}); put(root, 'blocked');
  fs.unlinkSync(path.join(root, 'directory')); fs.mkdirSync(path.join(root, 'directory'));
  fs.unlinkSync(path.join(root, 'dangling')); fs.symlinkSync('absent', path.join(root, 'dangling'));
  put(root, 'unselected', 'irrelevant');
  assert.deepEqual(verifyManifest(root, manifest), {
    ok:false, unchanged:['A', 'size', 'space tab\tline\n', 'é'],
    changed:[{path:'both', reasons:['content', 'mode']}, {path:'mode', reasons:['mode']}, {path:'z', reasons:['content']}],
    missing:['gone/file'], unsafe:['blocked/file', 'dangling', 'directory', 'link/file'],
  });
  assert.equal(JSON.stringify(manifest), before);
  const sizeOnly = createManifest(root, ['size']);
  sizeOnly.files[0].size = Number.MAX_SAFE_INTEGER;
  assert.deepEqual(verifyManifest(root, sizeOnly).changed, [{path:'size', reasons:['content']}]);
});

test('complete manifest validation and numeric boundaries', t => {
  const root = fixture(t); put(root, 'a');
  const valid = createManifest(root, ['a']);
  const entry = valid.files[0];
  const bad = [null, [], {}, {version:2, files:[]}, {version:1, files:{}},
    ...[null, [], {}, {...entry, path:''}, {...entry, sha256:entry.sha256 + '\n'},
      {...entry, sha256:'A'.repeat(64)}, {...entry, sha256:1},
      ...[-1, 1.5, NaN, Infinity, Number.MAX_SAFE_INTEGER + 1, '3'].map(size => ({...entry, size})),
      ...[-1, 512, 0.5, NaN, '1'].map(mode => ({...entry, mode}))
    ].map(e => ({version:1, files:[entry, e]})),
    {version:1, files:[entry, {...entry}]}];
  for (const manifest of bad) assert.throws(() => verifyManifest(root, manifest), Error);
  for (const selected of ['', '/a', 'a\\b', 'a\0b', 'a//b', './a', 'a/../b', 'a/', 3]) {
    assert.throws(() => createManifest(root, [selected]), Error);
    assert.throws(() => verifyManifest(root, {version:1, files:[{...entry, path:selected}]}), Error);
  }
  assert.throws(() => createManifest(root, ['a', 'a']), Error);
  assert.throws(() => createManifest(root, 'a'), Error);
  assert.deepEqual(verifyManifest(root, {version:1, files:[], extra:1}), blank());
  assert.equal(verifyManifest(root, {version:1, files:[{...entry, extra:true}], extra:1}).ok, true);
  for (const size of [0, Number.MAX_SAFE_INTEGER]) {
    assert.deepEqual(verifyManifest(root, {version:1, files:[{...entry, size}]}).changed, [{path:'a', reasons:['content']}]);
  }
  for (const mode of [0, 511]) assert.equal(verifyManifest(root, {version:1, files:[{...entry, mode}]}).ok, false);
});

test('root and selection safety applies to both APIs', t => {
  const root = fixture(t); put(root, 'file');
  fs.symlinkSync(root, path.join(root, 'alias'));
  fs.symlinkSync('file', path.join(root, 'link'));
  for (const invalidRoot of [path.join(root, 'absent'), path.join(root, 'file'), path.join(root, 'alias'), path.join(root, 'alias') + '/']) {
    assert.throws(() => createManifest(invalidRoot, []), Error);
    assert.throws(() => verifyManifest(invalidRoot, {version:1, files:[]}), Error);
  }
  for (const selected of ['link', 'alias/file', 'file/child', 'absent']) assert.throws(() => createManifest(root, [selected]), Error);
  assert.deepEqual(createManifest(root, []), {version:1, files:[]});
});

function cli(args, code, expected) {
  const result = spawnSync(process.execPath, [script, ...args], {encoding:'utf8'});
  assert.ifError(result.error);
  assert.equal(result.status, code, result.stderr);
  if (code === 2) {
    assert.equal(result.stdout, '');
    assert.ok(result.stderr.trim());
  } else {
    assert.equal(result.stderr, '');
    assert.equal(result.stdout, JSON.stringify(expected) + '\n');
  }
}

test('CLI success, drift, argument and input errors; import is silent', t => {
  const root = fixture(t); put(root, 'a');
  const manifest = createManifest(root, ['a']);
  const input = path.join(root, 'manifest.json');
  fs.writeFileSync(input, JSON.stringify(manifest));
  cli(['create', root, 'a'], 0, manifest);
  cli(['create', root], 0, {version:1, files:[]});
  cli(['verify', root, input], 0, {...blank(), unchanged:['a']});
  put(root, 'a', 'drift');
  cli(['verify', root, input], 1, {...blank(), ok:false, changed:[{path:'a', reasons:['content']}]});
  for (const args of [[], ['unknown'], ['create'], ['verify'], ['verify', root], ['verify', root, input, 'extra'],
    ['create', root, '../bad'], ['create', root, 'absent'], ['create', root, 'a', 'a'],
    ['create', input], ['verify', root, root], ['verify', root, input + '.absent'], ['verify', input, input]]) cli(args, 2);
  fs.writeFileSync(input, '{'); cli(['verify', root, input], 2);
  fs.writeFileSync(input, '{"version":1,"files":[{}]}'); cli(['verify', root, input], 2);
  const imported = spawnSync(process.execPath, ['--input-type=module', '-e', `import ${JSON.stringify(new URL('../snapshot.js', import.meta.url).href)}`], {encoding:'utf8'});
  assert.ifError(imported.error);
  assert.equal(imported.status, 0);
  assert.equal(imported.stdout, ''); assert.equal(imported.stderr, '');
});

